    #       · 3.5 ＋4,500 ｜ 3.6 ＋4,500（工具表与三张新表 ＋ 迁移，代码最多）
    #       · 3.7 ＋4,000 ｜ 3.8 ＋4,000 ｜ 3.9 ＋4,000（编排、护栏、追踪与评测各 ≈ 200 行）
