    #     【第七次修正（2026-09-13：接线小节的实际篇幅是估的两倍）】
    #     3.4 写完接线小节后实测：这一节从 0 长到 **3,997 有效字**（汉字 ＋1,372、
    #     代码 ＋175 行、另加两份输出块），而事前估的是 ＋2,000——**低估一倍**。
    #     错因与前几章不同：不是“没数围栏”，而是**胶水比零件长**。一段可独立验收的增量，
    #     真正占篇幅的不是那 120 行模块代码，而是接口契约表（哪些文件、什么签名、
    #     依赖前面哪一章）、验收命令与期望输出、以及“不能破坏什么”那四条边界。
