    #         （首字延迟 vs 总时长、SSE 与 WebSocket／轮询的分界）／SSE 的帧与三个头
    #         （`event`／`data`／`id`／`retry` 四字段、多行 `data` 拼接、注释帧当心跳；
    #         `Cache-Control`／`X-Accel-Buffering`／`Connection` 各挡什么，以及「本地像流、线上一吐一片」）／
    #         断线与续传（`Last-Event-ID`、`retry:` 与浏览器自动重连、服务端要存什么才能续、
    #         重复与丢失各发生在哪一段）／背压与慢消费者（队列增长、心跳间隔与超时、
    #         断开与无限缓冲之间没有第三个选项、并发连接数与 worker）／客户端状态机
    #         （idle→submitting→streaming→done／error／aborted、abort 的三个层次、
    #         三种「卡在流式中」的成因、部分片段与重试会不会重复）／AI SDK 的对照
